const input = $input.item;

// Preserve the binary file
const binaryKey = Object.keys(input.binary || {})[0];
const binary = binaryKey ? input.binary[binaryKey] : null;

const supplied = input.json.body ?? input.json;

const allowedMimes = [
  'application/pdf',
  'image/jpeg',
  'image/png'
];

const maxBytes = 10 * 1024 * 1024;

const mime = binary?.mimeType ?? supplied.mime_type ?? '';
const fileName = binary?.fileName ?? supplied.file_name ?? 'unknown';

// n8n stores the numeric size in bytes
const size = Number(
  binary?.bytes ??
  binary?.size ??
  supplied.file_size ??
  0
);

const violations = [];

if (!allowedMimes.includes(mime)) {
  violations.push('INT-01: Unsupported or missing file type');
}

if (size > maxBytes) {
  violations.push('INT-02: File exceeds 10 MB limit');
}

if (
  supplied.malware_scan_status &&
  supplied.malware_scan_status !== 'clean'
) {
  violations.push('INT-03: Malware scan did not pass');
}

const correlation_id = supplied.correlation_id || $execution.id;
const source_id = supplied.source_id || `SRC-${correlation_id}-${fileName}`;

return [{
  json: {
    correlation_id,
    source_id,

    document_metadata: {
      file_name: fileName,
      mime_type: mime,
      file_size: size,
      received_at: new Date().toISOString(),
      source_sha256: supplied.source_sha256 || null
    },

    intake_validation: {
      passed: violations.length === 0,
      violations
    },

    test_mode: supplied.test_mode === true,
    force_duplicate: supplied.force_duplicate === true
  },

  // ⭐ Preserve the binary for downstream nodes
  binary: input.binary
}];

// DEMO ONLY: replace with an atomic database insert/lookup on source_sha256.
// Production should use a UNIQUE(source_sha256) constraint.

const input = $input.item;

const item = input.json;

// Simulate duplicate detection
const duplicate = item.force_duplicate === true;

return [{
  json: {
    ...item,
    duplicate_check: {
      is_duplicate: duplicate,
      key: item.document_metadata.source_sha256 || item.source_id,
      checked_at: new Date().toISOString()
    }
  },

  // Preserve binary for downstream nodes
  binary: input.binary
}];

const item = $input.item.json;

const violations = [];

// ---------- Vendor Validation ----------
if (!item.vendor?.name) {
  violations.push("VAL-01: Vendor name is missing");
}

if (!item.vendor?.id) {
  violations.push("VAL-02: Vendor ID not found in Vendor Master");
}

// ---------- Invoice Validation ----------
if (!item.invoice?.number) {
  violations.push("VAL-03: Invoice number is missing");
}

if (!item.invoice?.issue_date) {
  violations.push("VAL-04: Invoice date is missing");
}

if (!item.invoice?.due_date) {
  violations.push("VAL-05: Due date is missing");
}

if (!item.invoice?.currency) {
  violations.push("VAL-06: Currency is missing");
}

// ---------- Amount Validation ----------
if (item.amounts?.subtotal == null || item.amounts.subtotal < 0) {
  violations.push("VAL-07: Invalid subtotal");
}

if (item.amounts?.tax == null || item.amounts.tax < 0) {
  violations.push("VAL-08: Invalid tax amount");
}

if (item.amounts?.total == null || item.amounts.total <= 0) {
  violations.push("VAL-09: Invalid total amount");
}

// ---------- Line Items ----------
if (!Array.isArray(item.line_items) || item.line_items.length === 0) {
  violations.push("VAL-10: No line items found");
}

// ---------- Confidence ----------
const confidence = item.confidence || {};

if (
  confidence.vendor_name != null &&
  confidence.vendor_name < 0.80
) {
  violations.push("VAL-11: Low confidence on Vendor Name");
}

if (
  confidence.invoice_number != null &&
  confidence.invoice_number < 0.80
) {
  violations.push("VAL-12: Low confidence on Invoice Number");
}

if (
  confidence.total_amount != null &&
  confidence.total_amount < 0.80
) {
  violations.push("VAL-13: Low confidence on Total Amount");
}

return [{
  json: {
    ...item,

    validation_policy: {
      version: "2.0",
      passed: violations.length === 0,
      violations,
      evaluated_at: new Date().toISOString()
    }
  },

  binary: $input.item.binary
}];

const item = $input.item.json;
const review = item.review_decision ?? item.body?.review_decision;
const reviewer = item.reviewer_id ?? item.body?.reviewer_id;
const decision = review === 'approved' && reviewer ? 'approved' : 'rejected';
return [{ json: { ...item, human_review: { decision, reviewer_id: reviewer || 'UNVERIFIED', correction_reason: item.correction_reason ?? item.body?.correction_reason ?? null, decided_at: new Date().toISOString() } } }];

